@export class ComponentWrapper{
  component: Component;
  id: number;
  other_data: Object;
  constructor(component: Component,id: number,other_data?: Object){
    this.component = component;
    this.id = id;
    this.other_data=other_data;
  }

}

@Component({
  selector: 'app-list',
  templateUrl: './list.component.html'
})

export class ListComponent{
